using ICSharpCode.Decompiler;
using ICSharpCode.Decompiler.CSharp;
using ICSharpCode.Decompiler.Metadata;
using ICSharpCode.Decompiler.TypeSystem;

namespace MadModStudio.ModAnalysis.Decompilation;

public sealed record DecompiledSource(bool Success, string Text, string? Error)
{
    public const string Banner =
        "// ============================================================================\n" +
        "//  DECOMPILED / RECONSTRUCTED SOURCE — NOT THE ORIGINAL SOURCE CODE\n" +
        "//  Generated by Mad Mod Studio from compiled IL using ICSharpCode.Decompiler.\n" +
        "//  Names, comments and structure may differ from the author's original.\n" +
        "// ============================================================================\n\n";
}

/// <summary>
/// Reconstructs C# from IL with ICSharpCode.Decompiler. The decompiler reads metadata/IL as data; the target assembly
/// is never loaded for execution.
/// </summary>
public sealed class DecompilerService
{
    public DecompiledSource DecompileType(string assemblyPath, string typeFullName, IEnumerable<string>? searchDirectories = null)
    {
        try
        {
            var decompiler = Create(assemblyPath, searchDirectories);
            var text = decompiler.DecompileTypeAsString(new FullTypeName(typeFullName.Replace('+', '/')));
            return new DecompiledSource(true, DecompiledSource.Banner + text, null);
        }
        catch (Exception ex)
        {
            return new DecompiledSource(false, "", $"Decompilation failed: {ex.Message}");
        }
    }

    public DecompiledSource DecompileAssembly(string assemblyPath, IEnumerable<string>? searchDirectories = null)
    {
        try
        {
            var decompiler = Create(assemblyPath, searchDirectories);
            var text = decompiler.DecompileWholeModuleAsString();
            return new DecompiledSource(true, DecompiledSource.Banner + text, null);
        }
        catch (Exception ex)
        {
            return new DecompiledSource(false, "", $"Decompilation failed: {ex.Message}");
        }
    }

    private static CSharpDecompiler Create(string assemblyPath, IEnumerable<string>? searchDirectories)
    {
        var settings = new DecompilerSettings(LanguageVersion.CSharp7_3)
        {
            ThrowOnAssemblyResolveErrors = false,
            LoadInMemory = true,
        };
        var module = new PEFile(assemblyPath, System.Reflection.PortableExecutable.PEStreamOptions.PrefetchEntireImage);
        var resolver = new UniversalAssemblyResolver(assemblyPath, false, module.DetectTargetFrameworkId());
        resolver.AddSearchDirectory(Path.GetDirectoryName(Path.GetFullPath(assemblyPath))!);
        if (searchDirectories != null)
            foreach (var d in searchDirectories.Where(Directory.Exists)) resolver.AddSearchDirectory(d);
        return new CSharpDecompiler(module, resolver, settings);
    }
}
